// Builds the NetForms website into ../_site: the static pages of site/ as they are, plus the documentation
// (docs/*.md in English, docs/ru/*.md in Russian, docs/api/*.md generated by NetForms.ApiDiff) rendered into
// the site's own layout. The Markdown stays the source and reads the same on GitHub: links between .md files
// become links between pages, links to anything else in the repository go to GitHub.
//   cd site && npm ci && npm run build && npm run serve
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { Marked, Renderer } from 'marked';

const site = path.dirname(fileURLToPath(import.meta.url));
const repo = path.resolve(site, '..');
const out = path.join(repo, '_site');
const github = 'https://github.com/Go-Forms/.NetForms';

// Every documentation page: its Markdown source (repository path) and where it lands on the site.
const sections = {
	en: {
		lang: 'en', home: '', docs: 'docs/',
		title: 'Documentation', other: 'ru', otherLabel: 'RU',
		nav: [
			['docs/README.md', 'docs/index.html', 'Overview'],
			['docs/install.md', 'docs/install.html', 'Install and set up'],
			['docs/getting-started.md', 'docs/getting-started.html', 'Getting started'],
			['docs/migrating.md', 'docs/migrating.html', 'Moving a WinForms project'],
			['docs/compatibility.md', 'docs/compatibility.html', 'Compatibility guide'],
			['docs/designer.md', 'docs/designer.html', 'The visual designer'],
			['docs/control-libraries.md', 'docs/control-libraries.html', 'Control libraries in the designer'],
			['docs/api/README.md', 'docs/api/index.html', 'API coverage'],
		],
		ui: { menu: 'Contents', edit: 'Edit this page on GitHub', start: 'Get started', site: 'Home', notice: '' },
	},
	ru: {
		lang: 'ru', home: 'ru/', docs: 'ru/docs/',
		title: 'Документация', other: 'en', otherLabel: 'EN',
		nav: [
			['docs/ru/README.md', 'ru/docs/index.html', 'Обзор'],
			['docs/ru/install.md', 'ru/docs/install.html', 'Установка и настройка'],
			['docs/ru/getting-started.md', 'ru/docs/getting-started.html', 'Первое приложение'],
			['docs/ru/migrating.md', 'ru/docs/migrating.html', 'Перевод WinForms-проекта'],
			['docs/ru/compatibility.md', 'ru/docs/compatibility.html', 'Совместимость'],
			['docs/ru/designer.md', 'ru/docs/designer.html', 'Визуальный дизайнер'],
			['docs/ru/control-libraries.md', 'ru/docs/control-libraries.html', 'Библиотеки элементов управления'],
			['docs/api/README.md', 'docs/api/index.html', 'Покрытие API (англ.)'],
			['docs/RELEASING.md', 'ru/docs/releasing.html', 'Выпуск версий (для разработчиков)'],
		],
		ui: { menu: 'Содержание', edit: 'Исправить страницу на GitHub', start: 'Начать', site: 'Главная', notice: '' },
	},
};

// Repository path -> site path, for every page and copied file; the rest of the repository links to GitHub.
const pages = new Map();
// English first: a page listed in both navigations (API coverage) is rendered once, in the English layout.
for (const s of Object.values(sections)) for (const [src, dst] of s.nav) if (!pages.has(src)) pages.set(src, { dst, section: s });
for (const f of fs.readdirSync(path.join(repo, 'docs', 'api'))) {
	if (f.endsWith('.md') && f !== 'README.md') pages.set(`docs/api/${f}`, { dst: `docs/api/${f.replace(/\.md$/, '.html')}`, section: sections.en });
}
const assets = new Map([['docs/images', 'docs/images']]);

function slug(text) {
	return text.toLowerCase().replace(/<[^>]+>/g, '').replace(/[^\p{L}\p{N}\- _]/gu, '').trim().replace(/ /g, '-');
}

function escapeHtml(s) {
	return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/** A link written in the Markdown file `from`, as the page `dst` must write it. */
function resolveLink(href, from, dst) {
	if (/^([a-z]+:|#|\/\/)/i.test(href)) return href;
	const [target, hash = ''] = href.split('#');
	const repoPath = path.posix.normalize(path.posix.join(path.posix.dirname(from), target));
	const anchor = hash ? '#' + hash : '';
	const page = pages.get(repoPath);
	let siteTarget = page?.dst;
	if (!siteTarget) {
		for (const [prefix, to] of assets) if (repoPath === prefix || repoPath.startsWith(prefix + '/')) siteTarget = to + repoPath.slice(prefix.length);
	}
	if (!siteTarget) {
		const kind = fs.existsSync(path.join(repo, repoPath)) && fs.statSync(path.join(repo, repoPath)).isDirectory() ? 'tree' : 'blob';
		return `${github}/${kind}/main/${repoPath}${anchor}`;
	}
	return path.posix.relative(path.posix.dirname(dst), siteTarget) + anchor;
}

function render(src, dst, section) {
	const markdown = fs.readFileSync(path.join(repo, src), 'utf8');
	let title = '';
	const toc = [];
	const marked = new Marked({ gfm: true });
	marked.use({
		renderer: {
			heading({ tokens, depth }) {
				const html = this.parser.parseInline(tokens);
				const id = slug(html);
				if (depth === 1 && !title) title = html.replace(/<[^>]+>/g, '');
				if (depth === 2) toc.push([id, html.replace(/<[^>]+>/g, '')]);
				return `<h${depth} id="${id}"><a class="anchor" href="#${id}" aria-hidden="true">#</a>${html}</h${depth}>\n`;
			},
			link({ href, title: t, tokens }) {
				return `<a href="${escapeHtml(resolveLink(href, src, dst))}"${t ? ` title="${escapeHtml(t)}"` : ''}>${this.parser.parseInline(tokens)}</a>`;
			},
			image({ href, title: t, text }) {
				return `<img src="${escapeHtml(resolveLink(href, src, dst))}" alt="${escapeHtml(text)}"${t ? ` title="${escapeHtml(t)}"` : ''} loading="lazy">`;
			},
			table(token) {
				return `<div class="table-scroll">${Renderer.prototype.table.call(this, token)}</div>\n`;
			},
			code({ text, lang }) {
				return `<pre class="code"${lang ? ` data-lang="${escapeHtml(lang)}"` : ''}><code>${escapeHtml(text)}</code></pre>\n`;
			},
		},
	});
	const body = marked.parse(markdown);
	const up = path.posix.relative(path.posix.dirname(dst), '.') || '.';
	const rel = (p) => path.posix.relative(path.posix.dirname(dst), p) || './';
	const nav = section.nav.map(([s, d, label]) =>
		`<li><a href="${rel(d)}"${d === dst ? ' aria-current="page"' : ''}>${escapeHtml(label)}</a></li>`).join('\n');
	const localToc = toc.length > 2
		? `<nav class="toc" aria-label="${section.lang === 'ru' ? 'На этой странице' : 'On this page'}"><ul>${toc.map(([id, t]) => `<li><a href="#${id}">${escapeHtml(t)}</a></li>`).join('')}</ul></nav>`
		: '';
	const otherSection = sections[section.other];
	const counterpart = otherSection.nav.find(([s]) => pageKey(s) === pageKey(src))?.[1] ?? otherSection.nav[0][1];
	const html = `<!doctype html>
<html lang="${section.lang}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>${escapeHtml(title)} — NetForms</title>
<link rel="icon" href="${up}/assets/favicon.png" type="image/png">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,400..800&family=JetBrains+Mono:wght@400;500;600;700&display=swap">
<link rel="stylesheet" href="${up}/assets/site.css">
</head>
<body class="docs-page">
<div class="wrap">
<header class="topbar">
  <a class="brand" href="${rel(section.home + 'index.html')}"><img src="${up}/assets/logo.svg" alt="" width="32" height="32">NetForms</a>
  <nav class="nav" aria-label="${section.lang === 'ru' ? 'Главное меню' : 'Main'}">
    <a href="${rel(section.home + 'index.html')}">${section.ui.site}</a>
    <a href="${rel(section.nav[0][1])}">${section.title}</a>
    <a href="${github}">GitHub</a>
    <a class="lang" href="${rel(counterpart)}" hreflang="${section.other}" lang="${section.other}" data-lang-choice="${section.other}">${section.otherLabel}</a>
  </nav>
</header>
<div class="docs">
  <nav class="docs-nav" aria-label="${section.ui.menu}">
    <details open><summary>${section.ui.menu}</summary><ul>${nav}</ul></details>
  </nav>
  <main class="prose">
${body}
    <p class="edit"><a href="${github}/blob/main/${src}">${section.ui.edit}</a></p>
  </main>
  ${localToc}
</div>
<footer>
  <span>NetForms · MIT</span>
  <nav aria-label="Footer"><a href="${github}">GitHub</a><a href="https://www.nuget.org/packages/NetForms">NuGet</a></nav>
</footer>
</div>
<script src="${up}/assets/site.js" defer></script>
</body>
</html>
`;
	const file = path.join(out, dst);
	fs.mkdirSync(path.dirname(file), { recursive: true });
	fs.writeFileSync(file, html);
}

/** The same page in both languages: docs/x.md and docs/ru/x.md. */
function pageKey(src) {
	return src.replace(/^docs\/ru\//, 'docs/');
}

function copyDir(from, to, skip = () => false) {
	fs.mkdirSync(to, { recursive: true });
	for (const e of fs.readdirSync(from, { withFileTypes: true })) {
		if (skip(e.name)) continue;
		const a = path.join(from, e.name), b = path.join(to, e.name);
		if (e.isDirectory()) copyDir(a, b, skip); else fs.copyFileSync(a, b);
	}
}

fs.rmSync(out, { recursive: true, force: true });
copyDir(site, out, (name) => ['node_modules', 'build.mjs', 'package.json', 'package-lock.json', 'README.md'].includes(name));
for (const [from, to] of assets) copyDir(path.join(repo, from), path.join(out, to));
let count = 0;
for (const [src, { dst, section }] of pages) {
	if (!fs.existsSync(path.join(repo, src))) throw new Error(`${src} is listed but does not exist`);
	render(src, dst, section);
	count++;
}
// Served as it is, without Jekyll.
fs.writeFileSync(path.join(out, '.nojekyll'), '');
console.log(`site: ${count} documentation pages -> ${path.relative(repo, out)}`);
